219	impl LVal {
220	    pub fn build(
221	        &self,
222	        program: &mut Program,
223	        my_ir_generator_info: &mut MyIRGeneratorInfo,
224	    ) -> Result<IRLValBuildResult, String> {
225	        let LVal::Default(ident, index_exps) = self;
226	        match my_ir_generator_info.symbol_tables.get(&ident.content) {
227	            Some(SymbolTableEntry::Variable(_, ptr)) => {
228	                let ptr = ptr.clone();
229	                // Build indexes.
230	                let mut index_values = vec![];
231	                for exp in index_exps {
232	                    let build = exp.build(program, my_ir_generator_info)?;
233	                    index_values.push(match build {
234	                        IRExpBuildResult::Const(int) => {
235	                            create_new_local_value(program, my_ir_generator_info)
236	                                .integer(int)
237	                        }
238	                        IRExpBuildResult::Value(value) => value,
239	                    })
240	                }
241	                // Get element.
242	                let result = get_element_in_ndarray(ptr, &index_values, program, my_ir_generator_info);
243	                Ok(result)
244	            }
245	            Some(SymbolTableEntry::Constant(_lval_type, int)) => Ok(IRLValBuildResult::Const(*int)),
246	            None => Err(format!("Undeclared LVal symbol: {}", ident.content)),
247	        }
248	    }
249	}
