    42	pub struct MyBBValueTable<'a> {
    43	    program: &'a Program,
    44	    fd: &'a FunctionData,
    45	    curr_time: i32,
    46	    register_user: [Option<Value>; 32],
    47	    register_used_time: [i32; 32], // LRU registers
    48	    local_value_location: HashMap<Value, usize>,
    49	}
